"""Types for contract fenon.hand_pose.video 1.1.0 (result schema), generated by scripts/generate_types.py. Do not edit."""

from __future__ import annotations

from typing import Literal

from pydantic import BaseModel, ConfigDict, Field


class Video(BaseModel):
    model_config = ConfigDict(
        extra="ignore",
    )
    width: int = Field(..., ge=1)
    height: int = Field(..., ge=1)
    fps: float = Field(..., description="Constant frame rate of the source video.", gt=0.0)
    frame_count: int = Field(..., ge=1)
    duration_s: float = Field(..., gt=0.0)


class ProcessedRange(BaseModel):
    model_config = ConfigDict(
        extra="ignore",
    )
    start_s: float = Field(..., ge=0.0)
    end_s: float = Field(..., gt=0.0)
    start_frame: int = Field(..., ge=0)
    end_frame: int = Field(..., ge=1)


class Camera(BaseModel):
    model_config = ConfigDict(
        extra="ignore",
    )
    model: Literal["pinhole"]
    focal_length_px: float = Field(
        ...,
        description="Focal length the model used, in pixels of the source frame.",
        gt=0.0,
    )
    principal_point_px: list[float] = Field(
        ...,
        description="Image centre [width / 2, height / 2].",
        max_length=2,
        min_length=2,
    )
    assumed: bool = Field(
        ...,
        description="True when the focal length is the model's assumption, not a calibration.",
    )


class HandPoseRunResult(BaseModel):
    model_config = ConfigDict(
        extra="ignore",
    )
    video: Video = Field(..., title="Video")
    range: ProcessedRange = Field(
        ...,
        description="The range actually processed, after clipping. end_frame is exclusive.",
        title="ProcessedRange",
    )
    joint_order: list[str]
    camera: Camera = Field(..., title="Camera")
